const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const DAYS=[
{date:'الخميس · ٩:٤١ مساءً',intro:'بعد يوم طويل في المعهد، كريم رجع لعب أونلاين. وسط اللعب ظهر اسم جديد.',contact:'سامي_برو',status:'متصل دلوقتي',messages:['لعبك حلو يا كريم، نادر ألاقي حد بيفهم اللعبة كده.','إنت في معهد إيه؟ حاسس إنك بتفهم في حاجات كتير.'],choices:[
{id:'warm',label:'ترد بلطف وتكمل كلام عن اللعبة',say:'تسلم يا صاحبي، الجيم كان حلو. نلعب تاني بكرة؟',reply:'أكيد. بقى عندي حد أكلمه وأنا بلعب.',fx:{trust:1},note:'بداية ودودة جدًا. المديح السريع ممكن يقرب الناس، ومش لوحده علامة خطر.'},
{id:'neutral',label:'تخلي الكلام في حدود اللعبة',say:'اللعبة حلوة فعلًا. أشوفك في الجيم.',reply:'تمام يا نجم، براحتك.',fx:{},note:'حطيت حدود بسيطة من غير خصام.'},
{id:'profile',label:'تفتح البروفايل وتشوفه',say:'فتحت حساب سامي شوية.',reply:'صورة قديمة، معلومات قليلة، وأصدقاء مشتركين مش واضحين.',fx:{awareness:1},note:'البروفايل الصغير مش إثبات لوحده، لكنه سبب للتأني.'},
{id:'sister',label:'تحكي لأختك نور إنك اتعرفت على لاعب جديد',say:'في واحد اسمه سامي بلعب معاه، شكله كويس.',reply:'حلو! بس خليك واخد وقتك لحد ما تعرفه أكتر.',fx:{support:1,sister:1},person:'نور',note:'شاركت حاجة بسيطة مع حد قريب منك.'}]},
{date:'الجمعة · ١٠:١٧ مساءً',intro:'بقالكم كذا ليلة بتلعبوا سوا. النهارده سامي بعتلك رسالة على الخاص.',contact:'سامي_برو',status:'آخر ظهور منذ دقيقة',messages:['بصراحة إنت أكتر واحد فاهمني في السيرفر.','تعالى نكلم بعض على تطبيق تاني، هنا الناس بتدخل في كلامنا.','وخليها بينا، مش كل حاجة لازم تتقال.'],choices:[
{id:'private',label:'تنقلوا الكلام لتطبيق خاص',say:'ماشي، ابعتلي هناك.',reply:'حلو. كده هنتكلم براحتنا.',fx:{trust:1,secrecy:1},note:'نقل الحديث لمكان خاص ومعاه طلب السرية بيقلل فرصة إن حد يلاحظ اللي بيحصل.'},
{id:'stay',label:'تفضلوا في نفس اللعبة',say:'خلينا هنا أحسن، ده المكان اللي بنلعب فيه.',reply:'زي ما تحب يا كريم، مفيش مشكلة.',fx:{awareness:1},note:'حافظت على مساحة عامة. مش لازم توافق عشان ترضي الطرف التاني.'},
{id:'why',label:'تسأله: ليه لازم نخليها سر؟',say:'هو في سبب إن الكلام يبقى سر؟',reply:'لا يا عم، بس الناس بتحب تتدخل وخلاص.',fx:{awareness:1,pressure:1},note:'سؤالك كشف إن فيه ضغط، وردّه حاول يقلل من حقك في السؤال.'},
{id:'friend',label:'تبعت لصاحبك يوسف وتطلب رأيه',say:'في حد اتعرفت عليه أونلاين وعايز ننقل الكلام برا اللعبة. رأيك؟',reply:'مش هحكم عليه، بس خليك في مكان تقدر تعمل فيه بلوك واحتفظ براحتك.',fx:{support:1,youssef:1},person:'يوسف',note:'استشرت شخصًا موثوقًا بدل ما تشيل الحيرة لوحدك.'}]},
{date:'السبت · ١١:٠٣ مساءً',intro:'قبل ما يخرج سامي من اللعب، بعتلك فيديو قصير ولقطة شاشة غريبة.',contact:'سامي_برو',status:'أرسل مقطعًا',messages:['شفت اللي حصل؟ الفيديو ده يثبت إنهم بيخفوا الحقيقة.','اللقطة دي واضحة أهو. أنا جبتها من حد جوه الموضوع.','إنت أكيد مش هتصدق أي حاجة وخلاص، صح؟'],choices:[
{id:'forward',label:'تشارك المقطع في جروب أصحابك',say:'بصوا الفيديو ده، حد فاهم حكايته؟',reply:'وصلت الرسالة. حد كتب: «استنى، المقطع مقصوص ومش باين مصدره».',fx:{exposure:1,pressure:1},note:'مشاركة مادة غير متحققة ممكن توسع أثرها حتى لو كان قصدك الاستفسار.'},
{id:'verify',label:'تدور على مصدر مستقل قبل ما تصدقه',say:'هشوف إذا فيه مصدر موثوق بيأكد الكلام.',reply:'مفيش مصدر واضح أو سياق كامل للمقطع.',fx:{awareness:2},note:'الفيديو واللقطة ممكن يتقصوا أو يتفبركوا. غياب المصدر سبب كافي لعدم إعادة النشر.'},
{id:'ask',label:'تسأل سامي عن المصدر الكامل',say:'فين المصدر الأصلي والتاريخ؟ عايز أشوف السياق كامل.',reply:'مش مهم المصدر، المهم إنك تفهم الرسالة.',fx:{awareness:1,pressure:1},note:'لما يتهرب الشخص من المصدر ويضغط عليك، دي علامة تستحق الانتباه.'},
{id:'mother',label:'تشارك شكك مع مامتك أو شخص كبير بتثق فيه',say:'في فيديو اتبعتلي ومش عارف أصدقه. ممكن نبص عليه سوا؟',reply:'طبعًا. ما نشاركوش لحد ما نعرف مصدره.',fx:{support:1,awareness:1,family:1},person:'شخص من الأسرة',note:'طلب رأي شخص موثوق خطوة حماية، مش ضعف.'}]},
{date:'الأحد · ٨:٥٦ مساءً',intro:'سامي بقى يسأل كريم عن ضغط الدراسة وخلافه مع أبوه. بعد شوية وصلت رسالة جديدة.',contact:'سامي_برو',status:'يكتب…',messages:['أبوك مش سامعك، صح؟ أنا الوحيد اللي واخد بالي من اللي جواك.','عندي شغل أونلاين سهل. بس ابعتلي بياناتك عشان أسجلك.','ولو مهتم بجد، متحكيش لحد لحد ما نظبطها.'],choices:[
{id:'data',label:'تبعت البيانات عشان تلحق الفرصة',say:'تمام، هبعتلك اللي محتاجه.',reply:'«سامي_برو» حفظ الرسالة.',fx:{secrecy:1,exposure:2,pressure:1},note:'البيانات الشخصية مش شرط لتقييم فرصة شغل. السرية والاستعجال معًا ضغط واضح.'},
{id:'details',label:'تطلب تفاصيل مكتوبة وتتحقق من الجهة',say:'ابعت اسم الجهة والتفاصيل كاملة، وهراجعها قبل أي خطوة.',reply:'خلينا بعدين، الموضوع محتاج ثقة.',fx:{awareness:1,pressure:1},note:'الجهة الحقيقية تقدر تقدم تفاصيل قابلة للتحقق بدون استعجال أو سرية.'},
{id:'father',label:'تحاول تفتح كلام مع أبوك عن ضغطك',say:'يا بابا، محتاج أتكلم معاك في حاجة مضايقاني. مش لازم نحلها دلوقتي.',reply:'أبوك سكت لحظة وقال: «ماشي، نتكلم بعد العشا».',fx:{support:1,family:2},person:'أبوك',note:'طلبت مساحة للكلام مع إن العلاقة مش سهلة.'},
{id:'sister2',label:'تطلب من نور تقعد معاك شوية',say:'نور، فاضية؟ حاسس إني متلخبط ومحتاج أحكي.',reply:'حاضر. أنا جنبك، احكي على مهلك.',fx:{support:1,sister:2},person:'نور',note:'التواصل ممكن يبدأ بطلب بسيط، مش لازم تكون عارف هتقول كل حاجة.'}]},
{date:'الإثنين · ١٢:٢٢ بعد منتصف الليل',intro:'عدّى يوم من غير لعب. سامي لاحظ إن كريم مش بيرد، وبعت ورا بعض.',contact:'سامي_برو',status:'٣ رسائل جديدة',messages:['إنت اختفيت ليه؟ أنا وقفت جنبك لما محدش كان موجود.','متقوليش إنك بقيت زيهم. كنت فاكر إنك مختلف.','محتاج منك مساعدة بسيطة، متتأخرش عليا.'],choices:[
{id:'money',label:'تبعتله مبلغ صغير عشان مايزعلش',say:'هبعتلك دلوقتي، بس مش هقدر أكتر من كده.',reply:'وصلت الرسالة. سامي رد: «عارف إنك مش هتخذلني».',fx:{pressure:2,exposure:1},note:'استخدام الذنب والصداقة لطلب المال ضغط، حتى لو المبلغ صغير.'},
{id:'boundary',label:'تقول إنك مش هتبعت فلوس أو بيانات',say:'مش هقدر أبعت فلوس أو بيانات. لو في مشكلة احكيها بوضوح.',reply:'سامي اتأخر في الرد. الرسالة اتقرت.',fx:{awareness:1,pressure:1},note:'وضعت حدًا واضحًا. مش مسؤول عن تهدئة غضب شخص يضغط عليك.'},
{id:'mute',label:'تكتم الإشعارات وتاخد وقتك',say:'كتمت المحادثة لحد ما أهدى وأفكر.',reply:'الموبايل سكت شوية. مفيش قرار لازم يتاخد حالًا.',fx:{awareness:1},note:'التأخير الآمن بيدي مساحة للتفكير. الضغط على رد فوري علامة مهمة.'},
{id:'youssef2',label:'تحكي ليوسف عن الرسائل وطلب الفلوس',say:'هو بيقول إني هخذله لو مبعتش. ممكن نتكلم؟',reply:'يوسف رد: «ده ضغط، مش لازم تواجهه لوحدك. أنا فاضي دلوقتي».',fx:{support:2,youssef:2},person:'يوسف',note:'صديق موثوق يقدر يسمعك من غير ما يلومك.'}]},
{date:'الثلاثاء · ٩:٠٨ مساءً',intro:'فتح كريم حساب سامي فلقى رسائل قديمة خاصة بينهما. بعدها ظهر إشعار من حساب جديد.',contact:'حساب غير معروف',status:'رسالة جديدة',messages:['«لو اختفيت، المحادثات دي ممكن توصل لناس تعرفهم».','وبعدها سامي بعت: «قابلني بكرة. مكان هادي. هتسلمني حاجة، ومش هتسأل عنها دلوقتي».','مفيش تفاصيل أكتر.'],choices:[
{id:'meet',label:'توافق على المقابلة عشان توقف التهديد',say:'ماشي، هاجي لوحدي. بس خلص الموضوع.',reply:'تم إرسال الموقع. مفيش تفاصيل عن الشيء المطلوب.',fx:{exposure:2,pressure:2,meet:1},note:'تهديد بنشر محادثات مع طلب مقابلة وتسليم شيء مجهول خطر حقيقي. ما تروحش وما تسلّمش أي شيء.'},
{id:'block',label:'تحفظ الرسائل وتحظر الحساب',say:'أخذت لقطات للتهديد، وبعدها عملت حظر للحساب.',reply:'الحساب لم يعد قادرًا على مراسلتك من هنا.',fx:{awareness:1,block:1},note:'حفظ الأدلة ثم الحظر قد يساعد. ما تمسحش المحادثة قبل حفظ ما يلزم.'},
{id:'report',label:'تبلّغ المنصة وتحتفظ بنسخة من الرسائل',say:'بلغت عن الحساب واحتفظت بنسخة من الرسائل والوقت.',reply:'استلمت المنصة البلاغ. احتفظ بنسخة آمنة خارج المحادثة.',fx:{awareness:1,report:1},note:'الإبلاغ للمنصة مع حفظ الأدلة خطوة عملية. ماتدخلش في تفاوض أو تهديد مقابل.'},
{id:'adult',label:'تكلم شخصًا موثوقًا فورًا وتطلب منه يفضل معاك',say:'في تهديد وطلب مقابلة. محتاجك جنبي دلوقتي، من غير لوم.',reply:'«أنا معاك. مش هتروح لأي مقابلة، وهنشوف الخطوة الآمنة سوا».',fx:{support:2,family:1,askhelp:1},person:'شخص موثوق',note:'وجود شخص معك أهم من التعامل مع التهديد وحدك. التهديد مش ذنبك.'}]},
{date:'الأربعاء · ٨:٣٠ مساءً',intro:'آخر يوم. فيه رسائل لسه مفتوحة، وفيه ناس ممكن تكلمهم. مش لازم تحل كل حاجة لوحدك.',contact:'سامي_برو',status:'ينتظر ردك',messages:['«الساعة ٩. متتأخرش. وماتقولش لحد».','المقابلة في مكان عام أو خاص؟ ما اتقالش. والشيء المطلوب لسه مجهول.'],choices:[
{id:'go',label:'تروح للمقابلة لوحدك',say:'خرجت من البيت من غير ما تقول لحد.',reply:'الحكاية تقف هنا قبل المقابلة. ما نعرضش تفاصيل أو مشاهد خطر.',fx:{meet:2,exposure:2},note:'ماتروحش لمقابلة مجهولة أو تسلّم شيئًا لا تعرف محتواه. أوقف التواصل واطلب مساعدة فورًا.'},
{id:'tell',label:'تشارك الرسائل مع شخص موثوق وتطلب مرافقة ودعم',say:'ورّيت الرسائل لشخص بثق فيه وطلبت منه يفضل معايا.',reply:'«هنفضل سوا. مش هتروح، وهنحفظ الرسائل ونطلب المساعدة المناسبة».',fx:{support:2,askhelp:1,family:1},person:'شخص موثوق',note:'الاستعانة بشخص موثوق الآن خطوة عملية. لا تواجه التهديد وحدك.'},
{id:'report2',label:'تبلّغ وتحظر، بعد حفظ الرسائل',say:'حفظت التهديد وبلغت المنصة وحظرت الحساب.',reply:'مافيش رد لازم تبعته. الخطوة الجاية تكون مع شخص موثوق.',fx:{awareness:1,report:1,block:1},note:'حفظ الدليل، الإبلاغ، ثم قطع التواصل خطوات مفيدة. أبلغ شخصًا تثق به أيضًا.'},
{id:'negotiate',label:'ترد على التهديد وتحاول تساومه',say:'لو مسحت كل حاجة هعمل اللي طلبته.',reply:'وصلت رسالتك، لكنك مش مطالب بالتفاوض مع شخص يهددك.',fx:{pressure:2,exposure:1},note:'التفاوض أو إرسال مزيد من المعلومات قد يزيد الضغط. توقف، واحفظ الأدلة، واطلب مساعدة.'}]}
];
const fresh=()=>({day:0,moves:0,tab:'chat',stats:{trust:0,isolation:0,secrecy:0,exposure:0,support:0,pressure:0,awareness:0},flags:{},logs:[],chat:[],ended:false,quiet:false});let state=fresh(),toastTimer;
const nums=['الأول','الثاني','الثالث','الرابع','الخامس','السادس','السابع'];
function save(){try{localStorage.setItem('matetkheda3sh-v1',JSON.stringify(state))}catch(e){}}
function load(){try{const x=JSON.parse(localStorage.getItem('matetkheda3sh-v1'));if(x&&x.day>=0&&x.day<7&&!x.ended){state=x;return true}if(x?.ended){state=x;return true}}catch(e){}return false}
function showToast(t){let x=$('#toast');x.textContent=t;x.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>x.classList.remove('show'),2100)}
function begin(){if(!state.chat.length)openDay();$('#start-screen').hidden=true;$('#game-screen').hidden=false;$('#end-screen').hidden=true;$('#story-side').classList.add('playing');$('#eyebrow').textContent='أسبوع واحد · موبايل واحد';$('#headline').innerHTML='كل خطوة<br><span>بتسيب أثر.</span>';$('#lead').textContent='حركتين بس كل يوم. اختار إيه تعمل، وسيب الأيام ترد عليك. تقدر تقرأ الرسائل أو الدفتر أو تكلم حد قريب.';$('#intro-details').hidden=true;$('#story-quote').hidden=true;$('#safe-note').hidden=true;render()}
function openDay(){const d=DAYS[state.day];state.moves=0;state.chat=[{who:'system',text:'يوم '+nums[state.day],time:d.date},{who:'system',text:d.intro}];if(state.day===0){state.chat.push({who:'them',text:d.messages[0],name:d.contact,time:'٩:٣٩'});state.chat.push({who:'them',text:d.messages[1],name:d.contact,time:'٩:٤١'})}else{let lead=d.messages[0];if(state.stats.support>=3&&state.day>=4)lead='نور بعتت: «أنا موجودة لو حابب تحكي، من غير ضغط».';if(state.stats.isolation>=3&&state.day>=4)lead='الموبايل ساكت شوية. في إشعار من سامي.';state.chat.push({who:'them',text:lead,name:d.contact,time:'٩:٤١'});d.messages.slice(1).forEach((m,i)=>state.chat.push({who:'them',text:m,name:d.contact,time:`٩:${48+i*4}`}))}if(state.day>0&&state.stats.support>0)state.chat.push({who:'system',text:`فيه ${state.stats.support>=3?'ناس قريبة':'حد قريب'} يقدر يسمعك لو حبيت.`});save()}
function render(){if(state.ended){showEnd();return}$('#day-label').textContent='اليوم '+nums[state.day];$('#time-label').textContent=DAYS[state.day].date;$('#move-count').textContent=state.moves===2?'مفيش حركات فاضلة':'حركة'+(state.moves===0?'تين':' واحدة')+' فاضلة';$('#progress-fill').style.width=`${((state.day*2+state.moves)/14)*100}%`;$$('.tab').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.setAttribute('aria-selected',b.dataset.tab===state.tab)});$$('.nav-dot').forEach(b=>b.classList.toggle('active',b.dataset.nav===state.tab));$('#unread-dot').hidden=state.tab!=='chat';$('#nav-hint').textContent=state.tab==='chat'?'موبايل كريم':state.tab==='notes'?'ملاحظات كريم':'جهات الاتصال';const el=$('#phone-content');el.innerHTML='';if(state.tab==='chat')renderChat(el);if(state.tab==='notes')renderNotes(el);if(state.tab==='people')renderPeople(el);el.scrollTop=el.scrollHeight;save()}
function renderChat(el){let d=DAYS[state.day];el.innerHTML=`<div class="scene-date">${d.date}</div><div class="contact-head"><div class="avatar">${(d.contact||'س')[0]}</div><div><b>${d.contact}</b><small>${d.status}</small></div></div><div id="messages">${state.chat.map(m=>bubble(m)).join('')}</div>`;if(state.moves<2){el.insertAdjacentHTML('beforeend',`<div class="choices-title">إيه اللي هتعمله؟ <span style="color:#89988e;font-weight:400">· الحركة ${state.moves+1} من ٢</span></div><div class="choice-list">${d.choices.map(c=>`<button class="choice ${c.fx.support||c.fx.awareness?'safe':''} ${c.fx.exposure||c.fx.meet||c.fx.money?'risky':''}" data-choice="${c.id}"><span class="choice-label">${c.label}</span><span class="choice-meta">هتاخد حركة واحدة · مش لازم تبرر قرارك</span></button>`).join('')}</div><div class="choice-note">مفيش اختيار هيوقف الحكاية. تقدر تكلم حد في أي وقت.</div>`)}else{el.insertAdjacentHTML('beforeend',`<div class="entry"><p>${state.day<6?'اليوم خلص. الإشعارات بدأت تهدى، وبكرة فيه حكاية تانية.':'الأسبوع خلص. اختياراتك هتحدد شكل اللحظة الجاية.'}</p></div><button class="primary advance" id="advance-button">${state.day<6?'كمل لبكرة':'شوف نهاية الأسبوع'} <span>←</span></button>`)}el.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(b.dataset.choice));$('#advance-button')?.addEventListener('click',advance)}
function bubble(m){return `<div class="bubble ${m.who==='me'?'me':m.who==='system'?'system':'them'}">${m.name?`<b>${m.name}: </b>`:''}${escapeHtml(m.text)}${m.time&&m.who!=='system'?`<time>${m.time}</time>`:''}</div>`}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

